import { useEffect } from 'react';
import { createPortal } from 'react-dom';
import { t } from '@/i18n/index.js';
import styles from './Toast.module.css';

interface ToastProps {
  message: string;
  /** Offers to take the action back; the toast closes once pressed. */
  onUndo?: (() => void) | undefined;
  onDone: () => void;
  /** How long it stays, in milliseconds. */
  duration?: number;
}

/**
 * A short line at the foot of the screen for something that just happened
 * and can be taken back: the session's undo pill, grown up. It leaves on its
 * own, so nothing has to be dismissed.
 */
export function Toast({ message, onUndo, onDone, duration = 4000 }: ToastProps): React.JSX.Element {
  useEffect(() => {
    const timer = window.setTimeout(onDone, duration);
    return () => {
      window.clearTimeout(timer);
    };
    // The caller passes a fresh onDone each render; the toast's life is set once.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [duration]);

  // Into the body, for the same reason the sheet goes there: a fixed
  // overlay stops being fixed to the viewport the moment any ancestor has
  // a transform, a filter or a backdrop-filter, and this app has glass.
  return createPortal(
    <div className={styles.toast} role="status">
      <span className={styles.message}>{message}</span>
      {onUndo !== undefined && (
        <button
          type="button"
          className={styles.undo}
          onClick={() => {
            onUndo();
            onDone();
          }}
        >
          {t('action.undo')}
        </button>
      )}
    </div>,
    document.body,
  );
}
